import { Metadata } from "next";
import fs from "node:fs";
import path from "node:path";

const siteUrl =
  process.env.NEXT_PUBLIC_SITE_URL || "https://inject3r.github.io";
const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "/ip-address-database";

export async function generateStaticParams() {
  const asnIndexPath = path.join(process.cwd(), "public", "data", "asn.json");

  if (!fs.existsSync(asnIndexPath)) {
    return [];
  }

  const asnIndex = JSON.parse(fs.readFileSync(asnIndexPath, "utf8")) as {
    asns?: Array<{ country_code?: string }>;
  };

  const uniqueCountries = new Set(
    (asnIndex.asns || [])
      .map((entry) => String(entry.country_code || "").trim())
      .filter(Boolean),
  );

  return Array.from(uniqueCountries).map((countryCode) => ({
    countryCode: countryCode.toLowerCase(),
  }));
}

interface ASNCountryLayoutProps {
  children: React.ReactNode;
  params: Promise<{ countryCode: string }> | { countryCode: string };
}

export async function generateMetadata({
  params,
}: ASNCountryLayoutProps): Promise<Metadata> {
  const resolvedParams = await Promise.resolve(params);
  const countryCode = resolvedParams.countryCode.toUpperCase();
  const asnPath = `${basePath}/asn/${resolvedParams.countryCode.toLowerCase()}`;

  return {
    title: `${countryCode} ASN Database`,
    description: `Explore ASN records, organization data, and routed network blocks for ${countryCode}. Search by provider, registry, and IP version.`,
    keywords: [
      `${countryCode} ASN`,
      `ASN database ${countryCode}`,
      `autonomous system numbers ${countryCode}`,
      `IP routing data ${countryCode}`,
      `provider lookup ${countryCode}`,
    ],
    alternates: {
      canonical: `${siteUrl}${asnPath}/`,
    },
    openGraph: {
      title: `${countryCode} ASN Database`,
      description: `Discover ASN records and network coverage for ${countryCode}.`,
      type: "website",
      url: `${siteUrl}${asnPath}/`,
      siteName: "IP Address Database",
      locale: "en_US",
    },
    twitter: {
      card: "summary_large_image",
      title: `${countryCode} ASN Database`,
      description: `ASN and network information for ${countryCode}.`,
      creator: "@inject3r",
    },
  };
}

export default function ASNCountryLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return <>{children}</>;
}
